package com.johnny.hotel.damage;import com.johnny.hotel.common.Result;import com.johnny.hotel.pagination.PageResult;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController@RequiredArgsConstructor@RequestMapping("/api/damage-assessments")@PreAuthorize("hasAnyRole('STAFF','FINANCE','MANAGER','OWNER','SUPER_ADMIN')") public class DamageAssessmentController{private final DamageAssessmentService service;
 @PostMapping@PreAuthorize("hasAnyRole('STAFF','MANAGER','OWNER','SUPER_ADMIN')")public Result<DamageAssessment> report(@Valid@RequestBody DamageRequests.Report request){return Result.success(service.report(request));}
 @PostMapping("/{id}/assess")@PreAuthorize("hasAnyRole('FINANCE','MANAGER','OWNER','SUPER_ADMIN')")public Result<DamageAssessment> assess(@PathVariable Long id,@Valid@RequestBody DamageRequests.Assess request){return Result.success(service.assess(id,request));}
 @GetMapping("/{id}")public Result<DamageAssessment> get(@PathVariable Long id){return Result.success(service.get(id));}
 @GetMapping public Result<PageResult<DamageAssessment>> list(@RequestParam(required=false)Long stayId,@RequestParam(required=false)Long roomId,@RequestParam(required=false)Integer status,@RequestParam(required=false)Integer responsibility,@RequestParam(required=false)Integer sourceType,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(service.list(stayId,roomId,status,responsibility,sourceType,page,pageSize));}
}
